<?php

declare(strict_types=1);

namespace Moat\Gate\Tests\Conformance;

/** Reads the shared vectors in conformance/vectors/crypto/ (generated by `pnpm vectors`). */
final class Vectors
{
    /** @return array<string, mixed> */
    public static function load(string $file): array
    {
        $path = \dirname(__DIR__, 4) . '/conformance/vectors/crypto/' . $file;
        $text = file_get_contents($path);
        if ($text === false) {
            throw new \RuntimeException("cannot read {$path}");
        }
        $data = json_decode($text, true, 512, JSON_THROW_ON_ERROR);
        if (!\is_array($data)) {
            throw new \RuntimeException("{$file} is not an object");
        }

        /** @var array<string, mixed> $data */
        return $data;
    }

    /**
     * The cases as PHPUnit data: name → [case].
     *
     * @return iterable<string, array{array<string, mixed>}>
     */
    public static function cases(string $file): iterable
    {
        $cases = self::load($file)['cases'] ?? null;
        if (!\is_array($cases)) {
            throw new \RuntimeException("{$file} has no cases");
        }
        foreach ($cases as $case) {
            if (!\is_array($case) || !\is_string($case['name'] ?? null)) {
                throw new \RuntimeException("{$file} has a case without a name");
            }
            /** @var array<string, mixed> $case */
            yield $case['name'] => [$case];
        }
    }

    public static function string(mixed $value): string
    {
        if (!\is_string($value)) {
            throw new \RuntimeException('expected a string in the vector file');
        }

        return $value;
    }

    public static function int(mixed $value): int
    {
        if (!\is_int($value)) {
            throw new \RuntimeException('expected an integer in the vector file');
        }

        return $value;
    }

    /** @return array<string, mixed> */
    public static function map(mixed $value): array
    {
        if (!\is_array($value)) {
            throw new \RuntimeException('expected an object in the vector file');
        }

        /** @var array<string, mixed> $value */
        return $value;
    }
}
